echo "import json
import os

# Read the JSON configuration
with open('/app/project_config.json', 'r') as f:
    config = json.load(f)

# Validation checks
required_fields = ['project_name', 'target_type', 'sources', 'headers', 'compiler', 'standard', 'optimization', 'include_dirs', 'library_dirs', 'libraries', 'defines', 'warnings', 'output_dir', 'clean_patterns']

errors = []
for field in required_fields:
    if field not in config:
        errors.append(f'Missing required field: {field}')

# Check target_type
if config['target_type'] not in ['executable', 'static_lib', 'shared_lib']:
    errors.append('Invalid target_type. Must be one of: executable, static_lib, shared_lib')

# Check source files for .cpp extension
for source in config['sources']:
    if not source.endswith('.cpp'):
        errors.append(f'Source file {source} does not have a .cpp extension')

# Check if include directories exist
for include_dir in config['include_dirs']:
    if not os.path.exists(include_dir):
        errors.append(f'Include directory {include_dir} does not exist')

# Write the generation report
report = {
    'status': 'success' if len(errors) == 0 else 'failure',
    'errors': errors,
    'generated_targets': ['Makefile', 'test_program.cpp'],
    'variables_defined': ['CC', 'CXXFLAGS', 'LDFLAGS', 'SOURCES', 'OBJECTS', 'OUTPUT', 'INCLUDE_DIRS', 'LIB_DIRS', 'LIBS', 'DEFINES', 'WARNINGS', 'OUTPUT_DIR', 'CLEAN_PATTERNS'],
    'validation_passed': len(errors) == 0
}

with open('/app/generation_report.json', 'w') as f:
    json.dump(report, f, indent=4)

# Write the Makefile content
makefile_content = """
# Generated Makefile for {config['project_name']}

CC = {config['compiler']}
CXXFLAGS = -std={config['standard']}

# Optimization flags
ifeq ({config['optimization']}, debug)
CXXFLAGS += -g
else ifeq ({config['optimization']}, release)
CXXFLAGS += -O2
endif

# Warning flags
ifeq ({config['warnings'][0]}, all)
CXXFLAGS += -Wall
else ifeq ({config['warnings'][0]}, extra)
CXXFLAGS += -Wextra
else ifeq ({config['warnings'][0]}, pedantic)
CXXFLAGS += -Wpedantic
endif

# Include directories
INCLUDE_DIRS = {config['include_dirs']}

# Library directories
LIB_DIRS = {config['library_dirs']}

# Libraries
LIBS = {config['libraries']}

# Defines
DEFINES = {config['defines']}

# Sources and objects
SOURCES = {config['sources']}
OBJECTS = $(SOURCES:.cpp=.o)

# Output
OUTPUT = $(OUTPUT_DIR){config['project_name']}

# Output directory
OUTPUT_DIR = {config['output_dir']}

# Clean patterns
CLEAN_PATTERNS = {config['clean_patterns']}

# Default target
all: $(OUTPUT)

# Pattern rule for compiling .cpp to .o
$(OUTPUT_DIR)%.o: $(OUTPUT_DIR)%.cpp
	$(CC) $(CXXFLAGS) $(DEFINES) -I$(INCLUDE_DIRS) -L$(LIB_DIRS) -o $@ $<

# Linking target
$(OUTPUT): $(OBJECTS)
	$(CC) $(CXXFLAGS) $(DEFINES) -I$(INCLUDE_DIRS) -L$(LIB_DIRS) -o $@ $(OBJECTS) $(LIBS)

# Dependency rules
-include $(OBJECTS:.o=.d)

# Clean target
clean:
	rm -f $(CLEAN_PATTERNS)

# Phony targets
.PHONY: all clean
"""

with open('/app/Makefile', 'w') as f:
    f.write(makefile_content)

# Write the test program
test_program_content = """
