    std::cout << "Test program for {config['project_name']}
";
    std::cout << "Using define: DEBUG = " << DEBUG << std"
";
    std::cout << "Linking with library: m
";
    return 0;
}
"""

with open('/app/test_program.cpp', 'w') as f:
    f.write(test_program_content)
